288	/// Validates a snapshot relative path: non-empty, `/`-separated, no leading
289	/// or trailing slash, no empty/`.`/`..` segments, no NUL bytes. Backslashes
290	/// are ordinary characters and Unicode is compared by code points without
291	/// normalization.
292	private func isValidRelativePath(_ path: String) -> Bool {
293	    let scalars = path.unicodeScalars
294	    guard let first = scalars.first, let last = scalars.last else { return false }
295	    guard first != "/", last != "/" else { return false }
296	    var segment = String.UnicodeScalarView()
297	    for scalar in scalars {
298	        if scalar == "/" {
299	            if segment.isEmpty || String(segment) == "." || String(segment) == ".." {
300	                return false
301	            }
302	            segment.removeAll(keepingCapacity: true)
303	        } else {
304	            if scalar == "\0" { return false }
305	            segment.append(scalar)
306	        }
307	    }
308	    return String(segment) != "." && String(segment) != ".."
309	}
