325	private func decodeFiles(_ value: JSONValue) throws -> [FileRecord] {
326	    guard case .array(let items) = value else {
327	        throw SnapshotDecodeError(message: "files must be an array")
328	    }
329	    var records: [FileRecord] = []
330	    var seenPaths = Set<String>()
331	    var previousPath: String?
332	    for item in items {
333	        guard case .object(let members) = item else {
334	            throw SnapshotDecodeError(message: "each file entry must be an object")
335	        }
336	        let keys = Set(members.map { $0.0 })
337	        guard members.count == 3, keys == ["path", "sha256", "size"] else {
338	            throw SnapshotDecodeError(message: "file entry has missing or extra fields")
339	        }
340	        let fields = Dictionary(members, uniquingKeysWith: { $1 })
341	
342	        guard case .string(let path) = fields["path"], isValidRelativePath(path) else {
343	            throw SnapshotDecodeError(message: "file entry has an invalid path")
344	        }
345	        guard case .string(let sha256) = fields["sha256"], isValidSha256(sha256) else {
346	            throw SnapshotDecodeError(message: "file entry has an invalid sha256")
347	        }
348	        guard case .number(let sizeLexeme) = fields["size"],
349	              sizeLexeme.first != "-",
350	              let size = Int64(sizeLexeme, radix: 10), size >= 0
351	        else {
352	            throw SnapshotDecodeError(message: "file entry has an invalid size")
353	        }
354	
355	        if seenPaths.contains(path) {
356	            throw SnapshotDecodeError(message: "duplicate path in files: \(path)")
357	        }
358	        if let previous = previousPath, !utf8Precedes(previous, path) {
359	            throw SnapshotDecodeError(message: "file entries are not sorted by path")
360	        }
361	        seenPaths.insert(path)
362	        previousPath = path
363	        records.append(FileRecord(path: path, sha256: sha256, size: size))
364	    }
365	    return records
366	}
