393	// MARK: - Snapshot rendering
394	
395	private func utcTimestamp() -> String {
396	    let formatter = DateFormatter()
397	    formatter.locale = Locale(identifier: "en_US_POSIX")
398	    formatter.timeZone = TimeZone(identifier: "UTC")
399	    formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'"
400	    return formatter.string(from: Date())
401	}
