429	private func isPath(_ path: String, inside ancestor: String) -> Bool {
430	    let ancestorComponents = (ancestor as NSString).pathComponents
431	    let pathComponents = (path as NSString).pathComponents
432	    return pathComponents.count >= ancestorComponents.count
433	        && Array(pathComponents.prefix(ancestorComponents.count)) == ancestorComponents
434	}
