436	private enum PublishError: Error {
437	    case destinationExists
438	    case io(String)
439	}
440	
441	/// Writes `json` to a staging file in the destination's own directory and
442	/// publishes it with `link(2)`, which fails with EEXIST instead of ever
443	/// overwriting an existing destination. The staging file is removed on every
444	/// failure path.
445	private func publishSnapshot(json: String, to snapshotPath: String) throws {
446	    let bytes = Data(json.utf8)
447	    let snapshotURL = URL(fileURLWithPath: snapshotPath)
448	    let parentPath = normalizedRoot(snapshotURL.deletingLastPathComponent().path)
449	    let tempName = String(
450	        format: ".macvault-snapshot.%d.%016llx.tmp",
451	        ProcessInfo.processInfo.processIdentifier,
452	        UInt64.random(in: 0...UInt64.max))
453	    let tempPath = (parentPath as NSString).appendingPathComponent(tempName)
454	
455	    let fd = open(tempPath, O_CREAT | O_EXCL | O_WRONLY, 0o644)
456	    guard fd >= 0 else {
457	        throw PublishError.io(
458	            "cannot create staging file: \(String(cString: strerror(errno)))")
459	    }
460	
461	    do {
462	        var offset = 0
463	        while offset < bytes.count {
464	            let written = bytes.withUnsafeBytes { rawBuffer -> Int in
465	                write(fd, rawBuffer.baseAddress!.advanced(by: offset), bytes.count - offset)
466	            }
467	            if written < 0 {
468	                if errno == EINTR { continue }
469	                throw PublishError.io("staging write failed: \(String(cString: strerror(errno)))")
470	            }
471	            offset += written
472	        }
473	        if fsync(fd) != 0 {
474	            throw PublishError.io("staging sync failed: \(String(cString: strerror(errno)))")
475	        }
476	        if close(fd) != 0 {
477	            throw PublishError.io("staging close failed: \(String(cString: strerror(errno)))")
478	        }
479	    } catch {
480	        close(fd)
481	        unlink(tempPath)
482	        throw error
483	    }
484	
485	    if link(tempPath, snapshotPath) != 0 {
486	        if errno == EEXIST {
487	            unlink(tempPath)
488	            throw PublishError.destinationExists
489	        }
490	        let message = "cannot publish snapshot: \(String(cString: strerror(errno)))"
491	        unlink(tempPath)
492	        throw PublishError.io(message)
493	    }
494	    unlink(tempPath)
495	}
