497	// MARK: - `snapshot`
498	
499	func runSnapshot(sourcePath: String, snapshotPath: String) -> Int32 {
500	    let fileManager = FileManager.default
501	
502	    var sourceIsDirectory: ObjCBool = false
503	    guard fileManager.fileExists(atPath: sourcePath, isDirectory: &sourceIsDirectory),
504	          sourceIsDirectory.boolValue
505	    else {
506	        writeStderr("error: not an existing directory: \(sourcePath)\n")
507	        return 64
508	    }
509	
510	    let sourceRoot = normalizedRoot(sourcePath)
511	    let snapshotURL = URL(fileURLWithPath: snapshotPath)
512	    let resolvedParent = normalizedRoot(snapshotURL.deletingLastPathComponent().path)
513	    let resolvedSnapshot = (resolvedParent as NSString)
514	        .appendingPathComponent(snapshotURL.lastPathComponent)
515	    guard !isPath(resolvedSnapshot, inside: sourceRoot) else {
516	        writeStderr("error: SNAPSHOT must not be located inside SOURCE: \(snapshotPath)\n")
517	        return 64
518	    }
519	
520	    guard !fileManager.fileExists(atPath: snapshotPath) else {
521	        writeStderr("error: snapshot destination already exists: \(snapshotPath)\n")
522	        return 73
523	    }
524	
525	    var errors: [CompareError] = []
526	    let files = enumerateRegularFiles(root: sourceRoot, errors: &errors)
527	
528	    var records: [FileRecord] = []
529	    for relative in files.sorted(by: utf8Precedes) {
530	        switch hashFile(root: sourceRoot, relativePath: relative) {
531	        case .success(let record): records.append(record)
532	        case .failure(let error): errors.append(error)
533	        }
534	    }
535	
536	    guard errors.isEmpty else {
537	        reportCollectionErrors(errors)
538	        return 74
539	    }
540	
541	    let json = renderSnapshot(records: records, capturedAt: utcTimestamp())
542	    do {
543	        try publishSnapshot(json: json, to: snapshotPath)
544	    } catch PublishError.destinationExists {
545	        writeStderr("error: snapshot destination already exists: \(snapshotPath)\n")
546	        return 73
547	    } catch PublishError.io(let message) {
548	        writeStderr("error: \(message)\n")
549	        return 1
550	    } catch {
551	        writeStderr("error: \(error)\n")
552	        return 1
553	    }
554	    return 0
555	}
556	
557	// MARK: - `snapshot-diff`
558	
559	func runSnapshotDiff(snapshotPath: String, currentPath: String) -> Int32 {
560	    let fileManager = FileManager.default
561	
562	    var currentIsDirectory: ObjCBool = false
563	    guard fileManager.fileExists(atPath: currentPath, isDirectory: &currentIsDirectory),
564	          currentIsDirectory.boolValue
565	    else {
566	        writeStderr("error: not an existing directory: \(currentPath)\n")
567	        return 64
568	    }
569	
570	    let snapshotData: Data
571	    do {
572	        snapshotData = try Data(contentsOf: URL(fileURLWithPath: snapshotPath))
573	    } catch {
574	        writeStderr("error: cannot read snapshot \(snapshotPath): \(error.localizedDescription)\n")
575	        return 65
576	    }
577	
578	    let snapshotRecords: [FileRecord]
579	    do {
580	        snapshotRecords = try decodeSnapshot(snapshotData)
581	    } catch let error as SnapshotDecodeError {
582	        writeStderr("error: invalid snapshot \(snapshotPath): \(error.message)\n")
583	        return 65
584	    } catch {
585	        writeStderr("error: invalid snapshot \(snapshotPath)\n")
586	        return 65
587	    }
588	
589	    let currentRoot = normalizedRoot(currentPath)
590	    var errors: [CompareError] = []
591	    let files = enumerateRegularFiles(root: currentRoot, errors: &errors)
592	
593	    var currentRecords: [FileRecord] = []
594	    for relative in files.sorted(by: utf8Precedes) {
595	        switch hashFile(root: currentRoot, relativePath: relative) {
596	        case .success(let record): currentRecords.append(record)
597	        case .failure(let error): errors.append(error)
598	        }
599	    }
600	
601	    guard errors.isEmpty else {
602	        reportCollectionErrors(errors)
603	        return 74
604	    }
605	
606	    let entries = sortEntries(computeDiff(
607	        oldRecords: snapshotRecords,
608	        newRecords: currentRecords))
